#!/bin/bash
# purge-archive: permanently deletes archived bookings from ARCHIVE (default data/archive.tsv).
# data/archive.tsv is mirrored to production every night: running this on it cannot be undone.
# Usage: bash tools/purge-archive --all | --before YYYY-MM-DD
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
    : > "$ARCHIVE.tmp"
    n=$(awk -F'\t' -v c="$2" -v out="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print > out; next } { n++ } END { print n+0 }' "$ARCHIVE")
    mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged $n row(s) before $2 from $ARCHIVE" ;;
  *) echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2 ;;
esac

arguments.new_string:
u=$(mktemp); printf '2025-01-01\taoi\t09:00\t10:00\tz\n2024-06-01\taoi\t09:00\t10:00\tw\n' > "$u"
out=$(ARCHIVE=$u bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same day) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $u" ] || { echo "purge output (same day): $out"; fail=1; }
[ "$(cat "$u")" = "$(printf '2025-01-01\taoi\t09:00\t10:00\tz')" ] || { echo "a row dated on the cutoff day must be kept"; fail=1; }
err=$(ARCHIVE=$u bash tools/purge-archive 2>&1 >/dev/null); [ $? = 2 ] || { echo "no args should exit 2"; fail=1; }
case "$err" in *"--before YYYY-MM-DD"*) ;; *) echo "usage must list --before: $err"; fail=1 ;; esac
rm -f "$t" "$u"; exit $fail

