spec/purge-archive.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
t2=$(mktemp); printf '# h\n2025-01-01\taoi\t09:00\t10:00\tz\n2024-06-01\taoi\t09:00\t10:00\tw\n' > "$t2"
out=$(ARCHIVE=$t2 bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed (same-date case)"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t2" ] || { echo "purge output (same-date case): $out"; fail=1; }
grep -q 'z$' "$t2" || { echo "purge --before deleted the row dated on the cutoff"; fail=1; }
usage=$(bash tools/purge-archive 2>&1 >/dev/null); [[ "$usage" == *"--before YYYY-MM-DD"* ]] || { echo "usage lacks --before: $usage"; fail=1; }
rm -f "$t" "$t2"; exit $fail

