#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a month 13 date should exit 2"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025-06-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "a day 32 date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "an out-of-range date deleted rows"; fail=1; }
rm -f "$t"

# a row dated exactly on the cutoff is kept; only rows before it are purged
t=$(mktemp); printf '2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same date) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output (same date): $out"; fail=1; }
grep -q 'z$' "$t" && grep -q 'y$' "$t" && ! grep -q 'x$' "$t" || { echo "same-date row was not kept"; fail=1; }
rm -f "$t"

# the usage line names every option
u=$(ARCHIVE=/dev/null bash tools/purge-archive 2>&1 >/dev/null); printf '%s' "$u" | grep -q -- '--before YYYY-MM-DD' || { echo "usage lacks --before: $u"; fail=1; }
exit $fail

