#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
# a row dated on the cutoff is kept; only the rows before it go
t2=$(mktemp); printf '2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t2"
ARCHIVE=$t2 bash tools/purge-archive --before 2025-01-01 >/dev/null || { echo "purge --before failed on the cutoff date"; fail=1; }
[ "$(cut -f5 "$t2" | paste -sd' ' -)" = "z y" ] || { echo "purge --before deleted the row dated on the cutoff"; fail=1; }
# a month or day out of range is a bad date too
ARCHIVE=$t2 bash tools/purge-archive --before 2025-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
# usage lists both options
err=$(ARCHIVE=$t2 bash tools/purge-archive 2>&1); [ $? = 2 ] && [ "$err" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage: $err"; fail=1; }
# --all reports the count of data rows it removed
t3=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t3"
out=$(ARCHIVE=$t3 bash tools/purge-archive --all) || { echo "purge --all failed"; fail=1; }
[ "$out" = "purged 2 row(s) from $t3" ] || { echo "purge --all output: $out"; fail=1; }
rm -f "$t" "$t2" "$t3"; exit $fail

