#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
rm -f "$t"

# 同じ日付の行は残す（data-files.md §保存期間と削除）
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same date) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "same-date output: $out"; fail=1; }
grep -q '^2025-01-01' "$t" && ! grep -q '^2024-12-31' "$t" || { echo "same-date row should be kept"; fail=1; }
rm -f "$t"

# 使い方の誤り: usage に --before が出る・何も消さない（cli-conventions.md §使い方・入力の誤り）
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n' > "$t"
err=$(ARCHIVE=$t bash tools/purge-archive --bogus 2>&1 >/dev/null); [ $? = 2 ] || { echo "unknown option should exit 2"; fail=1; }
[ "$err" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $err"; fail=1; }
err=$(ARCHIVE=$t bash tools/purge-archive --before 2>&1 >/dev/null); [ $? = 2 ] || { echo "--before without a value should exit 2"; fail=1; }
[ "$err" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line (no value): $err"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a usage error deleted rows"; fail=1; }
rm -f "$t"; exit $fail

